71	template <typename ArrowType>
72	arrow::Result<std::shared_ptr<arrow::Array>> to_arrow_array(
73	    const std::vector<QueryNode::Ptr> &input) {
74	  using CType = typename ArrowType::c_type;
75	  typename arrow::TypeTraits<ArrowType>::BuilderType builder;
76	  ARROW_RETURN_NOT_OK(builder.Reserve(input.size()));
77	
78	  for (auto &s : input) {
79	    ARROW_RETURN_NOT_OK(builder.Append(convert_node_to_value<CType>(s)));
80	  }
81	
82	  std::shared_ptr<arrow::Array> array;
83	  ARROW_RETURN_NOT_OK(builder.Finish(&array));
84	  return array;
85	}
86	
87	arrow::Result<std::shared_ptr<arrow::Array>> to_arrow_string_array(
88	    const std::vector<QueryNode::Ptr> &input) {
89	  arrow::StringBuilder builder;
90	  ARROW_RETURN_NOT_OK(builder.Reserve(input.size()));
91	
92	  for (auto &s : input) {
93	    ARROW_RETURN_NOT_OK(builder.Append(s->text()));
94	  }
95	
96	  std::shared_ptr<arrow::Array> array;
97	  ARROW_RETURN_NOT_OK(builder.Finish(&array));
98	  return array;
99	}
100	
101	arrow::Result<std::shared_ptr<arrow::Array>> to_arrow_bool_array(
102	    const std::vector<QueryNode::Ptr> &input) {
103	  arrow::BooleanBuilder builder;
104	  ARROW_RETURN_NOT_OK(builder.Reserve(input.size()));
105	
106	  for (auto &s : input) {
107	    // input is normalized to "true" or "false"
108	    ARROW_RETURN_NOT_OK(builder.Append(s->text() == "true"));
109	  }
110	
111	  std::shared_ptr<arrow::Array> array;
112	  ARROW_RETURN_NOT_OK(builder.Finish(&array));
113	  return array;
114	}
