533	DocFilter::Ptr QueryPlanner::build_doc_filter(
534	    const Segment::Ptr &seg, const QueryInfo::Ptr &query_info,
535	    std::unique_ptr<arrow::compute::Expression> &forward_filter,
536	    bool single_stage_search) {
537	  std::unique_ptr<ac::Declaration> forward_filter_plan;
538	  // if single stage search is not enabled, first run acero plan to get
539	  // forward bitmap, then filter during search. otherwise, filter forward
540	  // during search.
541	  if (forward_filter && !single_stage_search) {
542	    ac::RecordBatchReaderSourceNodeOptions source_options{
543	        seg->scan(query_info->get_forward_filter_field_names())};
544	    forward_filter_plan.reset(new ac::Declaration{ac::Declaration::Sequence({
545	        {"record_batch_reader_source", std::move(source_options)},
546	        {
547	            "project",
548	            ac::ProjectNodeOptions{{std::move(*forward_filter)},
549	                                   {kFieldIsValid}},
550	        },
551	    })});
552	    forward_filter.reset();
553	  }
554	  return std::make_shared<DocFilter>(seg, query_info,
555	                                     std::move(forward_filter_plan),
556	                                     std::move(forward_filter));
557	}
558	
559	Result<PlanInfo::Ptr> QueryPlanner::vector_scan(
560	    Segment::Ptr seg, QueryInfo::Ptr query_info,
561	    std::unique_ptr<arrow::compute::Expression> forward_filter,
562	    bool single_stage_search) {
563	  auto doc_filter =
564	      build_doc_filter(seg, query_info, forward_filter, single_stage_search);
565	
566	  int topn = query_info->query_topn();
567	  int batch_size = get_batch_size(*query_info, false);
568	  auto recall_node = std::make_shared<VectorRecallNode>(
569	      std::move(seg), std::move(query_info), std::move(doc_filter), batch_size,
570	      single_stage_search);
571	
572	  auto source_node_options =
573	      arrow::acero::SourceNodeOptions{recall_node->schema(), recall_node->gen(),
574	                                      arrow::compute::Ordering::Implicit()};
575	  ac::Declaration node{"source", source_node_options};
576	  // group by need to collect all docs
577	  if (!recall_node->query_info()->group_by()) {
578	    node = ac::Declaration{
579	        "fetch", {std::move(node)}, ac::FetchNodeOptions{0, topn}};
580	  }
581	  return std::make_shared<PlanInfo>(std::move(node), recall_node->schema());
582	}
583	
584	Result<PlanInfo::Ptr> QueryPlanner::invert_scan(
585	    Segment::Ptr seg, QueryInfo::Ptr query_info,
586	    std::unique_ptr<arrow::compute::Expression> forward_filter) {
587	  auto topn = query_info->query_topn();
588	  int batch_size = get_batch_size(*query_info, forward_filter != nullptr);
589	  auto recall_node =
590	      std::make_shared<InvertRecallNode>(seg, query_info, batch_size);
591	
592	  auto source_node_options =
593	      arrow::acero::SourceNodeOptions{recall_node->schema(), recall_node->gen(),
594	                                      arrow::compute::Ordering::Implicit()};
595	  ac::Declaration node{"source", source_node_options};
596	  if (forward_filter) {
597	    node = ac::Declaration{"filter",
598	                           {std::move(node)},
599	                           ac::FilterNodeOptions(std::move(*forward_filter))};
600	  }
601	
602	  auto schema = recall_node->schema();
603	  if (query_info->is_include_vector()) {
604	    std::vector<cp::Expression> expressions;
605	    std::vector<std::string> names =
606	        query_info->get_all_fetched_scalar_field_names();
607	    for (const auto &field_name : names) {
608	      expressions.emplace_back(cp::field_ref(field_name));
609	    }
610	    for (const auto &vector_field : query_info->selected_vector_fields()) {
611	      auto indexer = seg->get_combined_vector_indexer(vector_field.field_name);
612	      if (!indexer) {
613	        return tl::make_unexpected(Status::InvalidArgument(
614	            "vector indexer not found:", vector_field.field_name));
615	      }
616	      if (vector_field.field_schema_ptr->is_dense_vector()) {
617	        expressions.emplace_back(
618	            cp::call("fetch_vector", {cp::field_ref(LOCAL_ROW_ID)},
619	                     std::make_shared<FetchVectorOp::Options>(indexer, true)));
620	        schema = Util::append_field(*schema, vector_field.field_name,
621	                                    arrow::binary());
622	      } else {
623	        expressions.emplace_back(
624	            cp::call("fetch_sparse_vector", {cp::field_ref(LOCAL_ROW_ID)},
625	                     std::make_shared<FetchVectorOp::Options>(indexer, false)));
626	        schema = Util::append_field(*schema, vector_field.field_name,
627	                                    Util::sparse_type());
628	      }
629	      names.emplace_back(vector_field.field_name);
630	    }
631	    node = ac::Declaration{
632	        "project",
633	        {std::move(node)},
634	        ac::ProjectNodeOptions{std::move(expressions), std::move(names)}};
635	  }
636	
637	  node = ac::Declaration{
638	      "fetch", {std::move(node)}, ac::FetchNodeOptions{0, topn}};
639	  return std::make_shared<PlanInfo>(std::move(node), std::move(schema));
640	}
641	
642	Result<PlanInfo::Ptr> QueryPlanner::fts_scan(
643	    Segment::Ptr seg, QueryInfo::Ptr query_info,
644	    std::unique_ptr<arrow::compute::Expression> forward_filter,
645	    bool single_stage_search) {
646	  auto doc_filter =
647	      build_doc_filter(seg, query_info, forward_filter, single_stage_search);
648	
649	  auto topn = query_info->query_topn();
650	  int batch_size = get_batch_size(*query_info, false);
651	  auto recall_node = std::make_shared<FtsRecallNode>(
652	      std::move(seg), std::move(query_info), std::move(doc_filter), batch_size);
653	
654	  auto source_node_options =
655	      arrow::acero::SourceNodeOptions{recall_node->schema(), recall_node->gen(),
656	                                      arrow::compute::Ordering::Implicit()};
657	  ac::Declaration node{"source", source_node_options};
658	
659	  node = ac::Declaration{
660	      "fetch", {std::move(node)}, ac::FetchNodeOptions{0, topn}};
661	  return std::make_shared<PlanInfo>(std::move(node), recall_node->schema());
662	}
663	
664	int QueryPlanner::get_batch_size(const QueryInfo &info, bool has_later_filter) {
665	  // ref https://arrow.apache.org/docs/developers/cpp/acero.html#batch-size
666	  if (!info.query_orderbys().empty() || has_later_filter) {
667	    return 32 * 1024;
668	  }
669	  return std::min(info.query_topn(), 32U * 1024);
670	}
