87	arrow::Result<std::shared_ptr<arrow::Array>> to_arrow_string_array(
88	    const std::vector<QueryNode::Ptr> &input) {
89	  arrow::StringBuilder builder;
90	  ARROW_RETURN_NOT_OK(builder.Reserve(input.size()));
91	
92	  for (auto &s : input) {
93	    ARROW_RETURN_NOT_OK(builder.Append(s->text()));
94	  }
95	
96	  std::shared_ptr<arrow::Array> array;
97	  ARROW_RETURN_NOT_OK(builder.Finish(&array));
98	  return array;
99	}
