142	Result<cp::Expression> QueryPlanner::create_filter_node(
143	    const QueryNode *query_node) {
144	  const QueryNode *left = query_node->left_node();
145	  const QueryNode *right = query_node->right_node();
146	
147	  arrow::Expression left_exp;
148	  DataType data_type;
149	  if (left->op() == QueryNodeOp::Q_ID) {
150	    left_exp = cp::field_ref(left->text());
151	    auto field_schema = schema_->get_forward_field(left->text());
152	    data_type = field_schema->data_type();
153	  } else if (left->op() == QueryNodeOp::Q_FUNCTION_CALL) {
154	    const QueryFuncNode *func_node = dynamic_cast<const QueryFuncNode *>(left);
155	    const auto &func_name = func_node->get_func_name_node()->text();
156	    const auto &arguments = func_node->arguments();
157	    if (func_name == kFuncArrayLength) {
158	      left_exp =
159	          cp::call("list_value_length", {cp::field_ref(arguments[0]->text())});
160	      // assume array_length argument is uint32
161	      data_type = DataType::UINT32;
162	    } else {
163	      return tl::make_unexpected(
164	          Status::InvalidArgument("unexpected function call", func_name));
165	    }
166	  } else {
167	    LOG_ERROR("Unexpected left op. expr[%s]", query_node->text().c_str());
168	    return tl::make_unexpected(
169	        Status::InvalidArgument("unexpected left op", left->text()));
170	  }
171	
172	  cp::Expression right_exp;
173	  const std::string &filter_value = right->text();
174	  auto op = query_node->op();
175	  if (op == QueryNodeOp::Q_IS_NULL) {
176	    return cp::is_null(std::move(left_exp));
177	  } else if (op == QueryNodeOp::Q_IS_NOT_NULL) {
178	    return cp::is_valid(std::move(left_exp));
179	  }
180	
181	  // TODO: check invalid filter
182	  if (op == QueryNodeOp::Q_IN || op == QueryNodeOp::Q_CONTAIN_ALL ||
183	      op == QueryNodeOp::Q_CONTAIN_ANY) {
184	    const QueryListNode *list_node = dynamic_cast<const QueryListNode *>(right);
185	    auto array_res = create_array_from_list_node(
186	        FieldSchema::get_element_data_type(data_type), list_node);
187	    if (!array_res.ok()) {
188	      return tl::make_unexpected(Status::InvalidArgument(
189	          "create array failed", array_res.status().ToString()));
190	    }
191	    if (op == QueryNodeOp::Q_IN) {
192	      auto in_filter = cp::call(
193	          "is_in", {std::move(left_exp)},
194	          std::make_shared<cp::SetLookupOptions>(array_res.MoveValueUnsafe()));
195	      if (list_node->exclude()) {
196	        return cp::not_(std::move(in_filter));
197	      }
198	      return in_filter;
199	    }
200	    auto contain_filter =
201	        cp::call(op == QueryNodeOp::Q_CONTAIN_ALL ? kContainAll : kContainAny,
202	                 {std::move(left_exp)},
203	                 std::make_shared<ContainOp::Options>(
204	                     ContainOp::Args{array_res.MoveValueUnsafe(), data_type}));
205	    if (list_node->exclude()) {
206	      return cp::not_(std::move(contain_filter));
207	    }
208	    return contain_filter;
209	  }
210	
211	  switch (data_type) {
212	    case DataType::STRING: {
213	      if (op == sqlengine::QueryNodeOp::Q_LIKE) {
214	        return cp::call("match_like", {std::move(left_exp)},
215	                        cp::MatchSubstringOptions(filter_value));
216	      } else {
217	        right_exp = cp::literal(filter_value);
218	      }
219	      break;
220	    }
221	    case DataType::INT32: {
222	      int32_t int32_value;
223	      ailego::StringHelper::ToInt32(filter_value, &int32_value);
224	      right_exp = cp::literal(int32_value);
225	      break;
226	    }
227	    case DataType::UINT32: {
228	      uint32_t uint32_value;
229	      ailego::StringHelper::ToUint32(filter_value, &uint32_value);
230	      right_exp = cp::literal(uint32_value);
231	      break;
232	    }
233	    case DataType::INT64: {
234	      int64_t int64_value;
235	      ailego::StringHelper::ToInt64(filter_value, &int64_value);
236	      right_exp = cp::literal(int64_value);
237	      break;
238	    }
239	    case DataType::UINT64: {
240	      uint64_t uint64_value;
241	      ailego::StringHelper::ToUint64(filter_value, &uint64_value);
242	      right_exp = cp::literal(uint64_value);
243	      break;
244	    }
245	    case DataType::FLOAT: {
246	      float float_value;
247	      ailego::StringHelper::ToFloat(filter_value, &float_value);
248	      right_exp = cp::literal(float_value);
249	      break;
250	    }
251	    case DataType::DOUBLE: {
252	      double double_value;
253	      ailego::StringHelper::ToDouble(filter_value, &double_value);
254	      right_exp = cp::literal(double_value);
255	      break;
256	    }
257	    case DataType::BOOL: {
258	      std::string lower_filter_value;
259	      lower_filter_value.resize(filter_value.size());
260	      bool bool_value;
261	      std::transform(filter_value.begin(), filter_value.end(),
262	                     lower_filter_value.begin(), ::tolower);
263	      if (lower_filter_value == "true") {
264	        bool_value = true;
265	      } else if (lower_filter_value == "false") {
266	        bool_value = false;
267	      } else {
268	        LOG_ERROR("Unrecognized bool value: %s", filter_value.c_str());
269	        return tl::make_unexpected(
270	            Status::InvalidArgument("unexpected bool value", filter_value));
271	      }
272	      right_exp = cp::literal(bool_value);
273	      break;
274	    }
275	    default: {
276	      LOG_ERROR("filter to data type is not supported.");
277	      return tl::make_unexpected(Status::InvalidArgument(
278	          "filter to data type is not supported", data_type));
279	      break;
280	    }
281	  }
282	
283	  switch (op) {
284	    case sqlengine::QueryNodeOp::Q_EQ:
285	      return cp::equal(std::move(left_exp), std::move(right_exp));
286	    case sqlengine::QueryNodeOp::Q_NE:
287	      return cp::not_equal(std::move(left_exp), std::move(right_exp));
288	    case sqlengine::QueryNodeOp::Q_GT:
289	      return cp::greater(std::move(left_exp), std::move(right_exp));
290	    case sqlengine::QueryNodeOp::Q_LT:
291	      return cp::less(std::move(left_exp), std::move(right_exp));
292	    case sqlengine::QueryNodeOp::Q_GE:
293	      return cp::greater_equal(std::move(left_exp), std::move(right_exp));
294	    case sqlengine::QueryNodeOp::Q_LE:
295	      return cp::less_equal(std::move(left_exp), std::move(right_exp));
296	      // NOTE: Q_LIKE already handled above
297	
298	    default:
299	      return tl::make_unexpected(Status::InvalidArgument("unexpected op", op));
300	      break;
301	  }
302	  return tl::make_unexpected(Status::InvalidArgument("unexpected op", op));
303	}
304	
305	Result<cp::Expression> QueryPlanner::parse_filter(const QueryNode *query_node) {
306	  if (!query_node) {
307	    return cp::literal(true);
308	  }
309	  if (query_node->type() == QueryNode::QueryNodeType::REL_EXPR) {
310	    return create_filter_node(query_node);
311	  }
312	  if (query_node->type() == QueryNode::QueryNodeType::LOGIC_EXPR) {
313	    auto left = parse_filter(query_node->left_node());
314	    if (!left) {
315	      return left;
316	    }
317	    auto right = parse_filter(query_node->right_node());
318	    if (!right) {
319	      return right;
320	    }
321	    if (query_node->op() == QueryNodeOp::Q_AND) {
322	      return cp::and_(std::move(left.value()), std::move(right.value()));
323	    } else if (query_node->op() == QueryNodeOp::Q_OR) {
324	      return cp::or_(std::move(left.value()), std::move(right.value()));
325	    }
326	  }
327	  return tl::make_unexpected(
328	      Status::InvalidArgument("unexpected ", query_node->text()));
329	}
