344	
345	Result<PlanInfo::Ptr> QueryPlanner::make_physical_plan(
346	    const std::vector<Segment::Ptr> &segments, const std::string & /*trace_id*/,
347	    std::vector<sqlengine::QueryInfo::Ptr> *query_infos) {
348	  const std::string &table_name = schema_->name();
349	  if (segments.empty()) {
350	    LOG_ERROR("Segment not found [%s]", table_name.c_str());
351	    return tl::make_unexpected(
352	        Status::InvalidArgument("segment not found:", table_name));
353	  }
354	
355	  QueryInfo *query_info = (*query_infos)[0].get();
356	  LOG_DEBUG("Making plan for collection[%s] query_info[%s]", table_name.c_str(),
357	            query_info->to_string().c_str());
358	  int topn = query_info->query_topn();
359	  bool has_vector = query_info->vector_cond_info() != nullptr;
360	  bool has_fts = query_info->fts_cond_info() != nullptr;
361	  bool vector_is_reverse =
362	      has_vector && query_info->vector_cond_info()->is_reverse_sort();
363	  bool has_group_by = query_info->group_by() != nullptr;
364	
365	  // optimize plan by instrument query info condition, eg adjust invert cond
366	  Optimizer::Ptr optimizer =
367	      InvertCondOptimizer::CreateInvertCondOptimizer(schema_);
368	  int num_segments = segments.size();
369	  std::vector<PlanInfo::Ptr> segment_plans(segments.size());
370	  for (int idx = 0; idx < num_segments; ++idx) {
371	    auto &segment = segments[idx];
372	    auto &segment_query_info = (*query_infos)[idx];
373	    bool only_invert_before_opt =
374	        segment_query_info->invert_cond() != nullptr &&
375	        segment_query_info->filter_cond() == nullptr;
376	    if (optimizer) {
377	      // Optimize by change query info if needed.
378	      if (!optimizer->optimize(segment.get(), segment_query_info.get())) {
379	        LOG_DEBUG(
380	            "Not optimized. collection[%s] segment[%zu] "
381	            "segment_query_info[%s]",
382	            table_name.c_str(), (size_t)segment->id(),
383	            segment_query_info->to_string().c_str());
384	      } else {
385	        LOG_DEBUG(
386	            "Optimized. collection[%s] segment[%zu] segment_query_info[%s]",
387	            table_name.c_str(), (size_t)segment->id(),
388	            segment_query_info->to_string().c_str());
389	      }
390	    }
391	    bool only_forward_after_opt =
392	        segment_query_info->invert_cond() == nullptr &&
393	        segment_query_info->filter_cond() != nullptr;
394	    // if only invert cond before opt and only forward cond after opt,
395	    // single stage search should be performed as large ratio of docs match
396	    // with filter
397	    bool single_stage_search = only_invert_before_opt && only_forward_after_opt;
398	    std::unique_ptr<arrow::compute::Expression> forward_filter;
399	    if (segment_query_info->filter_cond()) {
400	      auto filter = parse_filter(segment_query_info->filter_cond().get());
401	      if (!filter) {
402	        LOG_ERROR("Parse filter failed: %s", filter.error().c_str());
403	        return tl::make_unexpected(filter.error());
404	      }
405	      forward_filter =
406	          std::make_unique<cp::Expression>(std::move(filter.value()));
407	    }
408	
409	    Result<PlanInfo::Ptr> seg_plan;
410	    if (segment_query_info->vector_cond_info()) {
411	      seg_plan = vector_scan(segment, std::move(segment_query_info),
412	                             std::move(forward_filter), single_stage_search);
413	    } else if (segment_query_info->fts_cond_info()) {
414	      seg_plan = fts_scan(segment, std::move(segment_query_info),
415	                          std::move(forward_filter), single_stage_search);
416	    } else if (segment_query_info->invert_cond()) {
417	      seg_plan = invert_scan(segment, std::move(segment_query_info),
418	                             std::move(forward_filter));
419	    } else {
420	      seg_plan = forward_scan(segment, std::move(segment_query_info),
421	                              std::move(forward_filter));
422	    }
423	    if (!seg_plan) {
424	      LOG_ERROR("Make plan failed: %s", seg_plan.error().c_str());
425	      return seg_plan;
426	    }
427	    if (segments.size() == 1) {
428	      return seg_plan;
429	    }
430	    segment_plans[idx] = std::move(seg_plan.value());
431	  }
432	
433	  // multi segment logic
434	  ailego::ThreadPool *pool = GlobalResource::Instance().query_thread_pool();
435	  auto recall_node =
436	      std::make_shared<SegmentNode>(std::move(segment_plans), pool);
437	  auto source_node_options =
438	      arrow::acero::SourceNodeOptions{recall_node->schema(), recall_node->gen(),
439	                                      arrow::compute::Ordering::Implicit()};
440	  ac::Declaration node{"source", source_node_options};
441	
442	  if (has_vector) {
443	    node = ac::Declaration{
444	        "order_by",
445	        {std::move(node)},
446	        ac::OrderByNodeOptions{cp::Ordering{{cp::SortKey{
447	            kFieldScore, vector_is_reverse ? cp::SortOrder::Descending
448	                                           : cp::SortOrder::Ascending}}}}};
449	  } else if (has_fts) {
450	    // FTS uses BM25 where higher score = more relevant. Per-segment results
451	    // are already in descending score order; merging multiple segments
452	    // requires a global re-sort to keep the contract.
453	    node = ac::Declaration{"order_by",
454	                           {std::move(node)},
455	                           ac::OrderByNodeOptions{cp::Ordering{{cp::SortKey{
456	                               kFieldScore, cp::SortOrder::Descending}}}}};
457	  }
458	
459	  // group by need to collect all docs
460	  if (!has_group_by) {
461	    node = ac::Declaration{
462	        "fetch", {std::move(node)}, ac::FetchNodeOptions{0, topn}};
463	  }
464	  return std::make_shared<PlanInfo>(std::move(node), recall_node->schema());
465	}
466	
467	Result<PlanInfo::Ptr> QueryPlanner::forward_scan(
468	    Segment::Ptr seg, QueryInfo::Ptr query_info,
469	    std::unique_ptr<arrow::compute::Expression> forward_filter) {
470	  auto reader = seg->scan(query_info->get_all_fetched_scalar_field_names());
471	  auto schema = reader->schema();
472	  ac::Declaration node{
473	      "record_batch_reader_source",
474	      ac::RecordBatchReaderSourceNodeOptions{std::move(reader)}};
475	
476	  auto seg_filter = seg->get_filter();
477	  if (seg_filter) {
478	    cp::Expression check_not_filtered =
479	        cp::call(kCheckNotFiltered, {cp::field_ref(LOCAL_ROW_ID)},
480	                 std::make_shared<CheckNotFilteredOp::Options>(seg_filter));
481	    node =
482	        ac::Declaration{"filter",
483	                        {std::move(node)},
484	                        ac::FilterNodeOptions(std::move(check_not_filtered))};
485	  }
486	
487	  if (forward_filter) {
488	    node = ac::Declaration{"filter",
489	                           {std::move(node)},
490	                           ac::FilterNodeOptions(std::move(*forward_filter))};
491	  }
492	
493	  if (query_info->is_include_vector()) {
494	    std::vector<cp::Expression> expressions;
495	    std::vector<std::string> names =
496	        query_info->get_all_fetched_scalar_field_names();
497	    for (const auto &field_name : names) {
498	      expressions.emplace_back(cp::field_ref(field_name));
499	    }
500	    for (const auto &vector_field : query_info->selected_vector_fields()) {
501	      auto indexer = seg->get_combined_vector_indexer(vector_field.field_name);
502	      if (!indexer) {
503	        return tl::make_unexpected(Status::InvalidArgument(
504	            "vector indexer not found:", vector_field.field_name));
505	      }
506	      if (vector_field.field_schema_ptr->is_dense_vector()) {
507	        expressions.emplace_back(
508	            cp::call("fetch_vector", {cp::field_ref(LOCAL_ROW_ID)},
509	                     std::make_shared<FetchVectorOp::Options>(indexer, true)));
510	        schema = Util::append_field(*schema, vector_field.field_name,
511	                                    arrow::binary());
512	      } else {
513	        expressions.emplace_back(
514	            cp::call("fetch_sparse_vector", {cp::field_ref(LOCAL_ROW_ID)},
515	                     std::make_shared<FetchVectorOp::Options>(indexer, false)));
516	        schema = Util::append_field(*schema, vector_field.field_name,
517	                                    Util::sparse_type());
518	      }
519	      names.emplace_back(vector_field.field_name);
520	    }
521	    node = ac::Declaration{
522	        "project",
523	        {std::move(node)},
524	        ac::ProjectNodeOptions{std::move(expressions), std::move(names)}};
525	  }
526	
527	  node = ac::Declaration{"fetch",
528	                         {std::move(node)},
529	                         ac::FetchNodeOptions{0, query_info->query_topn()}};
530	  return std::make_shared<PlanInfo>(std::move(node), std::move(schema));
531	}
532	
533	DocFilter::Ptr QueryPlanner::build_doc_filter(
534	    const Segment::Ptr &seg, const QueryInfo::Ptr &query_info,
535	    std::unique_ptr<arrow::compute::Expression> &forward_filter,
536	    bool single_stage_search) {
537	  std::unique_ptr<ac::Declaration> forward_filter_plan;
538	  // if single stage search is not enabled, first run acero plan to get
539	  // forward bitmap, then filter during search. otherwise, filter forward
540	  // during search.
541	  if (forward_filter && !single_stage_search) {
542	    ac::RecordBatchReaderSourceNodeOptions source_options{
543	        seg->scan(query_info->get_forward_filter_field_names())};
544	    forward_filter_plan.reset(new ac::Declaration{ac::Declaration::Sequence({
545	        {"record_batch_reader_source", std::move(source_options)},
546	        {
547	            "project",
548	            ac::ProjectNodeOptions{{std::move(*forward_filter)},
549	                                   {kFieldIsValid}},
550	        },
551	    })});
552	    forward_filter.reset();
553	  }
554	  return std::make_shared<DocFilter>(seg, query_info,
555	                                     std::move(forward_filter_plan),
556	                                     std::move(forward_filter));
557	}
558	
559	Result<PlanInfo::Ptr> QueryPlanner::vector_scan(
560	    Segment::Ptr seg, QueryInfo::Ptr query_info,
561	    std::unique_ptr<arrow::compute::Expression> forward_filter,
562	    bool single_stage_search) {
563	  auto doc_filter =
564	      build_doc_filter(seg, query_info, forward_filter, single_stage_search);
565	
566	  int topn = query_info->query_topn();
567	  int batch_size = get_batch_size(*query_info, false);
568	  auto recall_node = std::make_shared<VectorRecallNode>(
569	      std::move(seg), std::move(query_info), std::move(doc_filter), batch_size,
570	      single_stage_search);
571	
572	  auto source_node_options =
573	      arrow::acero::SourceNodeOptions{recall_node->schema(), recall_node->gen(),
574	                                      arrow::compute::Ordering::Implicit()};
575	  ac::Declaration node{"source", source_node_options};
576	  // group by need to collect all docs
577	  if (!recall_node->query_info()->group_by()) {
578	    node = ac::Declaration{
579	        "fetch", {std::move(node)}, ac::FetchNodeOptions{0, topn}};
580	  }
581	  return std::make_shared<PlanInfo>(std::move(node), recall_node->schema());
582	}
583	
584	Result<PlanInfo::Ptr> QueryPlanner::invert_scan(
585	    Segment::Ptr seg, QueryInfo::Ptr query_info,
586	    std::unique_ptr<arrow::compute::Expression> forward_filter) {
587	  auto topn = query_info->query_topn();
588	  int batch_size = get_batch_size(*query_info, forward_filter != nullptr);
589	  auto recall_node =
590	      std::make_shared<InvertRecallNode>(seg, query_info, batch_size);
591	
592	  auto source_node_options =
593	      arrow::acero::SourceNodeOptions{recall_node->schema(), recall_node->gen(),
594	                                      arrow::compute::Ordering::Implicit()};
595	  ac::Declaration node{"source", source_node_options};
596	  if (forward_filter) {
597	    node = ac::Declaration{"filter",
598	                           {std::move(node)},
599	                           ac::FilterNodeOptions(std::move(*forward_filter))};
600	  }
601	
602	  auto schema = recall_node->schema();
603	  if (query_info->is_include_vector()) {
604	    std::vector<cp::Expression> expressions;
605	    std::vector<std::string> names =
606	        query_info->get_all_fetched_scalar_field_names();
607	    for (const auto &field_name : names) {
608	      expressions.emplace_back(cp::field_ref(field_name));
609	    }
610	    for (const auto &vector_field : query_info->selected_vector_fields()) {
611	      auto indexer = seg->get_combined_vector_indexer(vector_field.field_name);
612	      if (!indexer) {
613	        return tl::make_unexpected(Status::InvalidArgument(
614	            "vector indexer not found:", vector_field.field_name));
615	      }
616	      if (vector_field.field_schema_ptr->is_dense_vector()) {
617	        expressions.emplace_back(
618	            cp::call("fetch_vector", {cp::field_ref(LOCAL_ROW_ID)},
619	                     std::make_shared<FetchVectorOp::Options>(indexer, true)));
620	        schema = Util::append_field(*schema, vector_field.field_name,
621	                                    arrow::binary());
622	      } else {
623	        expressions.emplace_back(
624	            cp::call("fetch_sparse_vector", {cp::field_ref(LOCAL_ROW_ID)},
625	                     std::make_shared<FetchVectorOp::Options>(indexer, false)));
626	        schema = Util::append_field(*schema, vector_field.field_name,
627	                                    Util::sparse_type());
628	      }
629	      names.emplace_back(vector_field.field_name);
630	    }
631	    node = ac::Declaration{
632	        "project",
633	        {std::move(node)},
634	        ac::ProjectNodeOptions{std::move(expressions), std::move(names)}};
635	  }
636	
637	  node = ac::Declaration{
638	      "fetch", {std::move(node)}, ac::FetchNodeOptions{0, topn}};
639	  return std::make_shared<PlanInfo>(std::move(node), std::move(schema));
640	}
641	
642	Result<PlanInfo::Ptr> QueryPlanner::fts_scan(
643	    Segment::Ptr seg, QueryInfo::Ptr query_info,
644	    std::unique_ptr<arrow::compute::Expression> forward_filter,
645	    bool single_stage_search) {
646	  auto doc_filter =
647	      build_doc_filter(seg, query_info, forward_filter, single_stage_search);
648	
649	  auto topn = query_info->query_topn();
650	  int batch_size = get_batch_size(*query_info, false);
651	  auto recall_node = std::make_shared<FtsRecallNode>(
652	      std::move(seg), std::move(query_info), std::move(doc_filter), batch_size);
653	
654	  auto source_node_options =
655	      arrow::acero::SourceNodeOptions{recall_node->schema(), recall_node->gen(),
656	                                      arrow::compute::Ordering::Implicit()};
657	  ac::Declaration node{"source", source_node_options};
658	
659	  node = ac::Declaration{
660	      "fetch", {std::move(node)}, ac::FetchNodeOptions{0, topn}};
661	  return std::make_shared<PlanInfo>(std::move(node), recall_node->schema());
662	}
663	
664	int QueryPlanner::get_batch_size(const QueryInfo &info, bool has_later_filter) {
665	  // ref https://arrow.apache.org/docs/developers/cpp/acero.html#batch-size
666	  if (!info.query_orderbys().empty() || has_later_filter) {
667	    return 32 * 1024;
668	  }
669	  return std::min(info.query_topn(), 32U * 1024);
670	}
